#include "../Source/RackModuleFactory.h"
#include "../Source/RackPresets.h"
#include <cassert>
#include <cstdio>
#include <fstream>
using namespace skl;
static void check(int type,int k,float v){assert(k>=0&&k<info(type).numKnobs);const auto& spec=info(type).knobs[k];assert(std::isfinite(v)&&v>=spec.lo&&v<=spec.hi);}
static std::vector<float> render(const std::vector<FSlot>& slots,const std::vector<float>& src){std::vector<float> a=src,b=src;std::vector<std::unique_ptr<ModuleBase>> modules;std::vector<std::array<float,6>> settings;for(const auto& s:slots){auto m=makeRackModule(s.type);assert(m);m->prepare(48000,257,2);modules.push_back(std::move(m));std::array<float,6> k{};for(int j=0;j<info(s.type).numKnobs;j++)k[j]=defaultNorm(s.type,j);for(auto [j,v]:s.set){check(s.type,j,v);k[j]=toNorm(info(s.type).knobs[j],v);}settings.push_back(k);}for(size_t i=0;i<a.size();i+=257){float* data[]={a.data()+i,b.data()+i};juce::AudioBuffer<float> buf(data,2,0,int(std::min<size_t>(257,a.size()-i)));for(size_t j=0;j<modules.size();j++)modules[j]->process(buf,settings[j].data(),true);}for(size_t i=0;i<a.size();i++)assert(std::isfinite(a[i])&&std::isfinite(b[i]));return a;}
int main(int argc,char**argv){int count=0;for(int t=1;t<kNumRackTypes;t++)for(auto& p:rackModulePresets(t)){assert(p.values.size()==size_t(info(t).numKnobs));for(size_t k=0;k<p.values.size();k++)check(t,int(k),p.values[k]);++count;}assert(count==39);std::vector<float> audio(96000);for(size_t i=0;i<audio.size();i++)audio[i]=.25f*std::sin(2*kPi*173*i/48000)+.07f*std::sin(2*kPi*5300*i/48000);if(argc>1){std::ifstream f(argv[1],std::ios::binary|std::ios::ate);assert(f&&f.tellg()>0);audio.resize(size_t(f.tellg())/sizeof(float));f.seekg(0);f.read(reinterpret_cast<char*>(audio.data()),audio.size()*sizeof(float));}for(size_t p=4;p<factory().size();p++){const auto& preset=factory()[p];assert(preset.slots.size()<=kNumSlots);const auto output=render(preset.slots,audio);float peak=0;double rms=0;for(float v:output){peak=std::max(peak,std::abs(v));rms+=v*v;}assert(peak<1.0f&&peak>0.001f);printf("%s: peak %.2f dBFS RMS %.2f dBFS\n",preset.name,20*log10(peak),10*log10(rms/output.size()));}puts("39 module settings and 3 new factory renders passed");}
